('public.nh7_video_authorize_v392(uuid, text, text, uuid, text)','a0a40205416b4c92197a4416e4b0c9aa','f5dcb386517edde72824f74ff09584e5','{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}'),
('public.nh7_video_portal_authorize_v251(text, uuid, text)','2c92b80d9aa39869876c46f1d13f9477','752a3f8e1b93d7793cddcfc67ef78670','{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}'),
('public.nh7_video_portal_authorize_v270(text, text, uuid, text)','adfec7959095ba1fe0598966f8ddd9b4','2e928de7bd6f77d543ab85a4d692596e','{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}'),
('public.nh7_video_portal_authorize_v392(text, text, uuid, text)','25f39762f5b54deffeaa1f1449473eb1','4a87e075c7993e48b601443385090b6f','{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}')) SELECT e.*,p.oid::regprocedure actual,md5(pg_get_functiondef(p.oid)) actual_definition_md5,
md5(p.prosrc) actual_body_md5,p.proacl actual_acl,p.prosecdef,p.proconfig,pg_get_userbyid(p.proowner) owner,
has_function_privilege('anon',p.oid,'EXECUTE') anon_execute,
has_function_privilege('authenticated',p.oid,'EXECUTE') authenticated_execute
FROM expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.signature);
-- Capture exact view ACLs, definitions/owners/options/dependencies privately for rollback; no data SELECT.
SELECT c.oid::regclass relation,pg_get_viewdef(c.oid,true) definition,md5(pg_get_viewdef(c.oid,true)) definition_md5,c.relacl,c.reloptions,pg_get_userbyid(c.relowner) owner
FROM pg_class c WHERE c.oid IN ('public.nh7_library_items_v224'::regclass,'public.nh7_library_items_v251'::regclass,'public.nh7_library_collections_public_v251'::regclass,'public.nh7_library_collections_public_v322'::regclass);
SELECT a.attrelid::regclass relation,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod) type
FROM pg_attribute a WHERE a.attrelid IN ('public.nh7_library_items_v224'::regclass,'public.nh7_library_items_v251'::regclass,'public.nh7_library_collections_public_v251'::regclass,'public.nh7_library_collections_public_v322'::regclass) AND a.attnum>0 AND NOT a.attisdropped ORDER BY a.attrelid,a.attnum;
-- Helper and nested authority fingerprints must be checked privately; never infer from names/markers.
SELECT p.oid::regprocedure,md5(pg_get_functiondef(p.oid)),md5(p.prosrc),p.prosecdef,p.proacl,p.proconfig
FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('private','auth') OR p.proname IN ('nh7_is_admin','nh7_admin_is_admin','nh7_admin_is_admin_v170','nh7_admin_has_permission_v395','nh7_school_registration_payload_error_v351','nh7_request_user_key','nh7_device_id');
-- Exact 29 Advisor entries, not raw system-schema census.
WITH target(name) AS (VALUES
('nh7_library_recovery_20260906.before_state'),
('nh7_library_recovery_20260906.chunks'),
('nh7_library_recovery_20260906.sources'),
('nh7_library_recovery_20260906.targets'),
('private.nh7_admin_audit_log_v350'),
('private.nh7_admin_members_v350'),
('private.nh7_admin_permission_catalog_v350'),
('private.nh7_admin_permission_grants_v350'),
('public._nh7_book_master_stage_14_21'),
('public.nh7_account_content_grants_v251'),
('public.nh7_admin_account_actions_v380'),
('public.nh7_apocrypha_books_v270'),
('public.nh7_content_entitlements_v380'),
('public.nh7_legacy_auth_claim_audit'),
('public.nh7_library_claim_codes_v433'),
('public.nh7_library_import_history_v434'),
('public.nh7_notification_runtime_secret'),
('public.nh7_school_audio_progress_v380'),
('public.nh7_school_video_code_items_v392'),
('public.nh7_school_video_codes_v260'),
('public.nh7_school_video_grants_v260'),
('public.nh7_school_videos_v260'),
('public.nh7_sermon_blessings_v440'),
('public.nh7_sermon_likes_v440'),
('public.notification_dispatch_log'),
('public.notification_schedule'),
('public.school_course_stage_lessons'),
('public.school_course_stages'),
('public.school_student_identities')) SELECT t.name,c.relrowsecurity,c.relforcerowsecurity,c.relacl,pg_get_userbyid(c.relowner) owner,
(SELECT count(*) FROM pg_policy p WHERE p.polrelid=c.oid) policies,
has_table_privilege('anon',c.oid,'SELECT') anon_select,has_table_privilege('authenticated',c.oid,'SELECT') auth_select,
has_table_privilege('anon',c.oid,'INSERT,UPDATE,DELETE') anon_any_write,has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE') auth_any_write
FROM target t LEFT JOIN pg_class c ON c.oid=to_regclass(t.name);
-- Extension-owned routines + dependencies, without exposing webhook/cron secret bodies.
SELECT e.extname,e.extversion,e.extrelocatable,e.extnamespace::regnamespace,pg_get_userbyid(e.extowner),p.oid::regprocedure,p.proacl,p.prosecdef
FROM pg_extension e LEFT JOIN pg_depend d ON d.refclassid='pg_extension'::regclass AND d.refobjid=e.oid AND d.classid='pg_proc'::regclass LEFT JOIN pg_proc p ON p.oid=d.objid WHERE e.extname='pg_net';
SELECT d.classid::regclass,d.objid,d.objsubid,d.refclassid::regclass,d.refobjid,d.deptype FROM pg_depend d WHERE d.refobjid IN (SELECT oid FROM pg_proc WHERE pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('net','public'))) AND d.refclassid='pg_proc'::regclass;
-- Full Delete: exact columns/constraints/triggers, no real rows, nested JSON ownership still owner-reviewed.
SELECT table_schema,table_name,column_name,data_type,udt_name FROM information_schema.columns WHERE table_schema IN ('public','private','storage','auth') ORDER BY table_schema,table_name,ordinal_position;
SELECT conrelid::regclass,confrelid::regclass,conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE contype='f';
SELECT tgrelid::regclass,tgname,tgfoid::regprocedure,tgenabled FROM pg_trigger WHERE NOT tgisinternal;
ROLLBACK;
